def own_lines(pages: list[str]) -> list[str]:
    """Each page of a paged read without the lines every page shares (menus, headers, footers), so the model's share
    of each page is its own rows: run_47ad55e7841ae0d7 read a 4-page register, the row it needed fell past the
    2,250 characters shown per page, and the agent clicked around for 10 steps."""
    if len(pages) < 2:
        return pages
    common = set.intersection(*(set(p.splitlines()) for p in pages))
    common = {line for line in common if line.strip()}
    return ["\n".join(line for line in p.splitlines() if line not in common) for p in pages]


