"""Run `jobs` at once, each in a tab of this scraper's browser (the tabs share its login cookies). A tab whose
job ended goes back to the scheduler's pool with its logged-in page, so the next job on this site (a mail lane,
a follow-up) starts there instead of a new tab that loads and logs in again. A failed job returns
{"summary": error, "done": False}."""
from swarm.scheduler import scheduler
b = self.browser if browser is None else browser

async def one(job: str) -> dict:
    async with scheduler(self.ctx).lease(self.site_id, prefer=b, only=b) as tab:
        try:
            return await self.browse_until_done(job, attempts=attempts, tab=tab, **kwargs)
        except Exception as error:
            self.ctx.board.error(self.name, f"tab job failed: {error}")
            tab.suspect = True
            return {"summary": str(error), "done": False}
return list(await asyncio.gather(*(one(job) for job in jobs)))

